{
  "name": "harbor-city",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "0.184.0"
  },
  "devDependencies": {
    "vite": "^7.0.0"
  }
}

import * as THREE from 'three';

export const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (min, max) => min + Math.random() * (max - min);
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

export function seededRandom(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

export function canvasTexture(width, height, draw) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

export function makeFacadeTexture({ base = '#b9b2a6', accent = '#ffc46b', cols = 5, rows = 8, seed = 1, lit = 0.35, style = 'grid' }) {
  const rnd = seededRandom(seed);
  const diffuse = canvasTexture(256, 512, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, base);
    grad.addColorStop(0.55, shade(base, -8));
    grad.addColorStop(1, shade(base, -18));
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);

    // vertical structure
    ctx.globalAlpha = 0.22;
    ctx.fillStyle = shade(base, 16);
    for (let x = 0; x < w; x += w / (cols + 1)) ctx.fillRect(x, 0, 3, h);
    ctx.globalAlpha = 1;

    const top = h * 0.08;
    const usable = h * 0.84;
    const cellW = w / cols;
    const cellH = usable / rows;
    for (let r = 0; r < rows; r++) {
      ctx.fillStyle = shade(base, r % 2 === 0 ? -3 : -7);
      ctx.fillRect(0, top + r * cellH, w, 2);
      for (let c = 0; c < cols; c++) {
        const x = c * cellW + cellW * 0.18;
        const y = top + r * cellH + cellH * 0.2;
        const ww = cellW * 0.64;
        const hh = cellH * 0.56;
        const litWindow = rnd() < lit;
        const g = ctx.createLinearGradient(x, y, x + ww, y + hh);
        if (litWindow) {
          g.addColorStop(0, '#ffe9b0');
          g.addColorStop(1, '#e8a75f');
        } else {
          g.addColorStop(0, '#2d4250');
          g.addColorStop(1, '#16222c');
        }
        ctx.fillStyle = g;
        ctx.fillRect(x, y, ww, hh);
        ctx.strokeStyle = 'rgba(12,18,24,.45)';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, y, ww, hh);
        if (style === 'lux' && c % 2 === 0) {
          ctx.fillStyle = 'rgba(255,255,255,.1)';
          ctx.fillRect(x + ww * 0.12, y, 2, hh);
        }
      }
    }

    // subtle grime / texture
    ctx.globalAlpha = 0.1;
    for (let i = 0; i < 80; i++) {
      ctx.fillStyle = i % 2 ? '#000' : '#fff';
      ctx.fillRect(rnd() * w, rnd() * h, rnd() * 18 + 2, 1);
    }
    ctx.globalAlpha = 1;

    // accent edge
    ctx.fillStyle = accent;
    ctx.globalAlpha = 0.8;
    ctx.fillRect(0, 0, w, 4);
    ctx.globalAlpha = 1;
  });

  const emissive = canvasTexture(256, 512, (ctx, w, h) => {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);
    const rnd2 = seededRandom(seed + 99);
    const top = h * 0.08;
    const usable = h * 0.84;
    const cellW = w / cols;
    const cellH = usable / rows;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (rnd2() < lit) {
          const x = c * cellW + cellW * 0.18;
          const y = top + r * cellH + cellH * 0.2;
          const ww = cellW * 0.64;
          const hh = cellH * 0.56;
          const g = ctx.createLinearGradient(x, y, x + ww, y + hh);
          g.addColorStop(0, '#fff4d2');
          g.addColorStop(1, '#ffbb68');
          ctx.fillStyle = g;
          ctx.fillRect(x, y, ww, hh);
        }
      }
    }
  });

  diffuse.wrapS = diffuse.wrapT = THREE.RepeatWrapping;
  emissive.wrapS = emissive.wrapT = THREE.RepeatWrapping;
  return { diffuse, emissive };
}

export function shade(hex, amount) {
  const c = new THREE.Color(hex);
  c.offsetHSL(0, 0, amount / 255);
  return `#${c.getHexString()}`;
}

export function makeSignTexture(text, { color = '#ffd7a2', bg = '#11141d', accent = '#ff8a5b', sub = '', width = 1024, height = 256 } = {}) {
  return canvasTexture(width, height, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    const r = 30;
    ctx.fillStyle = bg;
    roundRect(ctx, 6, 6, w - 12, h - 12, r);
    ctx.fill();
    ctx.strokeStyle = accent;
    ctx.lineWidth = 8;
    roundRect(ctx, 12, 12, w - 24, h - 24, r - 6);
    ctx.stroke();

    ctx.shadowColor = color;
    ctx.shadowBlur = 28;
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `900 ${sub ? 112 : 128}px "Arial Black", Impact, sans-serif`;
    ctx.fillText(text.toUpperCase(), w / 2, sub ? h * 0.44 : h * 0.52);
    ctx.shadowBlur = 0;

    if (sub) {
      ctx.fillStyle = 'rgba(255,255,255,.72)';
      ctx.font = '600 34px "Segoe UI", Arial, sans-serif';
      ctx.letterSpacing = '8px';
      ctx.fillText(sub.toUpperCase(), w / 2, h * 0.79);
    }

    // accent ticks
    ctx.fillStyle = accent;
    ctx.fillRect(w * 0.08, h - 22, w * 0.12, 5);
    ctx.fillRect(w * 0.8, h - 22, w * 0.12, 5);
  });
}

export function makeTextTexture(text, { color = '#ffffff', bg = 'rgba(10,14,20,.86)', accent = '#58e6d2', width = 512, height = 128, font = 56 } = {}) {
  return canvasTexture(width, height, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = bg;
    roundRect(ctx, 4, 4, w - 8, h - 8, 26);
    ctx.fill();
    ctx.strokeStyle = accent;
    ctx.lineWidth = 4;
    roundRect(ctx, 8, 8, w - 16, h - 16, 22);
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `800 ${font}px "Segoe UI", Arial, sans-serif`;
    ctx.fillText(text, w / 2, h / 2 + 2);
  });
}

export function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

let glowTexture = null;
export function getGlowTexture() {
  if (glowTexture) return glowTexture;
  glowTexture = canvasTexture(128, 128, (ctx, w, h) => {
    const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    g.addColorStop(0, 'rgba(255,255,255,1)');
    g.addColorStop(0.2, 'rgba(255,255,255,.8)');
    g.addColorStop(0.5, 'rgba(255,255,255,.2)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
  return glowTexture;
}

export function makeGlow(color = 0xffc46b, size = 2, opacity = 0.8) {
  const mat = new THREE.SpriteMaterial({
    map: getGlowTexture(),
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(size, size, 1);
  return sprite;
}

export function disposeObject(obj) {
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose?.();
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => m.dispose?.());
    }
  });
}

export function formatMoney(value) {
  return `$${Math.round(value).toLocaleString('en-US')}`;
}

export function formatTime(minutes) {
  const m = ((minutes % 1440) + 1440) % 1440;
  const h24 = Math.floor(m / 60);
  const min = Math.floor(m % 60);
  const suffix = h24 >= 12 ? 'PM' : 'AM';
  const h = h24 % 12 || 12;
  return `${h}:${String(min).padStart(2, '0')} ${suffix}`;
}

export function worldPos(col, row) {
  return { x: col * 60 - 120, z: row * 60 - 120 };
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { makeGlow } from './utils.js';

const shadowGeo = new THREE.CircleGeometry(1, 20);
const shadowMat = new THREE.MeshBasicMaterial({
  color: 0x000000,
  transparent: true,
  opacity: 0.2,
  depthWrite: false,
});
const shadowMatSoft = new THREE.MeshBasicMaterial({
  color: 0x000000,
  transparent: true,
  opacity: 0.12,
  depthWrite: false,
});

export function addShadow(parent, x, z, scale = 1, soft = false) {
  const s = new THREE.Mesh(shadowGeo, soft ? shadowMatSoft : shadowMat);
  s.rotation.x = -Math.PI / 2;
  s.position.set(x, 0.025, z);
  s.scale.set(scale, scale, scale);
  s.renderOrder = 1;
  parent.add(s);
  return s;
}

export function createHuman({
  shirt = 0xe86b4f,
  pants = 0x293241,
  skin = 0xf0c6a3,
  hair = 0x2a211d,
  role = 'pedestrian',
  height = 1,
  shoes = 0x191b22,
} = {}) {
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);

  const skinMat = new THREE.MeshStandardMaterial({ color: skin, roughness: 0.72 });
  const shirtMat = new THREE.MeshStandardMaterial({ color: shirt, roughness: 0.8 });
  const pantsMat = new THREE.MeshStandardMaterial({ color: pants, roughness: 0.86 });
  const hairMat = new THREE.MeshStandardMaterial({ color: hair, roughness: 0.9 });
  const shoeMat = new THREE.MeshStandardMaterial({ color: shoes, roughness: 0.7 });

  const legL = new THREE.Group();
  const legR = new THREE.Group();
  const legGeo = new THREE.CapsuleGeometry(0.105, 0.52, 4, 8);
  const shoeGeo = new RoundedBoxGeometry(0.19, 0.13, 0.34, 2, 0.05);
  for (const [leg, side] of [[legL, -1], [legR, 1]]) {
    leg.position.set(side * 0.145, 0.82, 0);
    const mesh = new THREE.Mesh(legGeo, pantsMat);
    mesh.position.y = -0.34;
    leg.add(mesh);
    const shoe = new THREE.Mesh(shoeGeo, shoeMat);
    shoe.position.set(0, -0.72, 0.07);
    leg.add(shoe);
    body.add(leg);
  }

  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.27, 0.42, 4, 10), shirtMat);
  torso.position.y = 1.08;
  torso.scale.z = 0.82;
  body.add(torso);

  const hips = new THREE.Mesh(new RoundedBoxGeometry(0.5, 0.22, 0.34, 2, 0.08), pantsMat);
  hips.position.y = 0.77;
  body.add(hips);

  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.1, 0.12, 8), skinMat);
  neck.position.y = 1.49;
  body.add(neck);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.225, 16, 12), skinMat);
  head.position.y = 1.69;
  head.scale.set(0.93, 1.05, 0.94);
  body.add(head);

  const hairCap = new THREE.Mesh(new THREE.SphereGeometry(0.235, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.62), hairMat);
  hairCap.position.y = 1.73;
  hairCap.scale.set(0.96, 0.92, 0.98);
  body.add(hairCap);

  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x1b1b20 });
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 5), eyeMat);
    eye.position.set(side * 0.078, 1.7, 0.205);
    body.add(eye);
  }

  const armGeo = new THREE.CapsuleGeometry(0.09, 0.44, 4, 7);
  const handGeo = new THREE.SphereGeometry(0.095, 8, 6);
  const armL = new THREE.Group();
  const armR = new THREE.Group();
  for (const [arm, side] of [[armL, -1], [armR, 1]]) {
    arm.position.set(side * 0.345, 1.3, 0);
    arm.rotation.z = side * 0.08;
    const mesh = new THREE.Mesh(armGeo, shirtMat);
    mesh.position.y = -0.28;
    arm.add(mesh);
    const hand = new THREE.Mesh(handGeo, skinMat);
    hand.position.y = -0.55;
    arm.add(hand);
    body.add(arm);
  }

  let accessory = null;

  if (role === 'police') {
    shirtMat.color.set(0x2b3b55);
    pantsMat.color.set(0x1c2534);
    const vest = new THREE.Mesh(new RoundedBoxGeometry(0.56, 0.52, 0.36, 2, 0.06), new THREE.MeshStandardMaterial({ color: 0x3e5474, roughness: 0.6 }));
    vest.position.y = 1.13;
    body.add(vest);
    const badge = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.12, 0.02), new THREE.MeshStandardMaterial({ color: 0xffd15c, metalness: 0.7, roughness: 0.3 }));
    badge.position.set(-0.13, 1.23, 0.19);
    body.add(badge);
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.235, 0.245, 0.16, 12), new THREE.MeshStandardMaterial({ color: 0x1a2740, roughness: 0.7 }));
