    body.add(cap);
  } else if (role === 'chef') {
    const hat = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 0.3, 12), new THREE.MeshStandardMaterial({ color: 0xf4f2eb }));
    hat.position.y = 1.95;
    body.add(hat);
