    accessory = 'backpack';
  }

  if (role === 'pedestrian') {
    // A few pedestrians get a shoulder bag or beanie.
    if (Math.random() < 0.25) {
      const bag = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.3, 0.34), new THREE.MeshStandardMaterial({ color: 0x5b4636, roughness: 0.9 }));
      bag.position.set(0.35, 0.95, 0.02);
