Index: src/interiors.js
===================================================================
--- src/interiors.js
+++ src/interiors.js
@@ -1,7 +1,7 @@
 import * as THREE from 'three';
 import { BUSINESSES, SHOP_ITEMS, DIALOGUE, NAMES, SKINS, HAIRS, pick } from './data.js';
-import { makeSignTexture, makeGlow, pick as choose } from './utils.js';
+import { makeSignTexture, makeGlow } from './utils.js';
 import { createHuman, animateHuman, addShadow } from './entities.js';

 const roomSizes = {
   mall: [28, 20],

input.content:
:root {
  --ink: #f6f2e8;
  --muted: #a9b4c2;
  --dim: #778392;
  --panel: rgba(10, 16, 24, 0.78);
  --panel-strong: rgba(8, 12, 18, 0.94);
  --line: rgba(255, 255, 255, 0.12);
  --cyan: #58e6d2;
  --orange: #ffb45c;
  --coral: #ff7c6b;
  --violet: #b78bff;
  --green: #8fd46a;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
  --radius: 18px;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0b1018;
  color: var(--ink);
  font-family: "Inter", "SF Pro Display", "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  touch-action: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }

#game, #game canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.hidden { display: none !important; }

.screen-fx { position: fixed; inset: 0; pointer-events: none; z-index: 2; }
.vignette {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(0,0,0,.22) 75%, rgba(0,0,0,.55) 110%);
}
.grain {
  position: absolute; inset: 0; opacity: .045; mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
}

.glass {
  background: var(--panel);
  border: 1px solid var(--line);
  backdrop-filter: blur(18px) saturate(1.15);
  -webkit-backdrop-filter: blur(18px) saturate(1.15);
  box-shadow: 0 10px 36px rgba(0,0,0,.22);
}

/* ---------------------------------------------------------------- splash */

.start-screen {
  position: fixed; inset: 0; z-index: 20;
  display: flex; flex-direction: column;
  padding: calc(26px + var(--safe-top)) calc(5vw + var(--safe-right)) calc(22px + var(--safe-bottom)) calc(5vw + var(--safe-left));
  background:
    linear-gradient(180deg, rgba(4,8,13,.78) 0%, rgba(4,8,13,.12) 38%, rgba(4,8,13,.12) 58%, rgba(4,8,13,.94) 100%),
    radial-gradient(ellipse at 70% 40%, transparent 20%, rgba(3,6,10,.28) 80%);
  transition: opacity .65s ease, visibility .65s;
}
.start-screen::after {
  content: ""; position: absolute; inset: auto 0 0 0; height: 34vh; pointer-events: none;
  background: linear-gradient(0deg, rgba(4,8,13,.96), transparent);
}
.start-screen.leaving { opacity: 0; visibility: hidden; }

.start-topbar { display: flex; justify-content: space-between; align-items: center; position: relative; z-index: 2; }
.live-pill {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 9px 14px; border-radius: 999px;
  border: 1px solid rgba(255,255,255,.14);
  background: rgba(9,14,21,.55); backdrop-filter: blur(12px);
  font-size: 11px; letter-spacing: .16em; font-weight: 800;
}
.live-pill i { width: 7px; height: 7px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 12px var(--cyan); animation: livePulse 1.8s infinite; }
@keyframes livePulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .45; transform: scale(.7); } }
.start-top-actions { display: flex; align-items: center; gap: 14px; font-size: 12px; color: var(--muted); }
.icon-btn {
  width: 40px; height: 40px; border-radius: 50%;
  display: grid; place-items: center; font-size: 17px;
  border: 1px solid var(--line); background: rgba(8,13,20,.55);
  transition: .2s;
}
.icon-btn:hover { border-color: rgba(88,230,210,.5); color: var(--cyan); }

.start-content {
  position: relative; z-index: 2;
  margin: auto 0;
  width: min(760px, 94%);
  padding-bottom: 4vh;
  animation: startIn .9s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes startIn { from { opacity: 0; transform: translateY(22px); } to { opacity: 1; transform: translateY(0); } }
.eyebrow { font-size: 11px; letter-spacing: .34em; color: var(--cyan); font-weight: 800; margin-bottom: 14px; text-shadow: 0 0 18px rgba(88,230,210,.45); }
.logo {
  margin: 0;
  display: flex; flex-direction: column; align-items: flex-start;
  font-family: "Arial Black", "Impact", system-ui, sans-serif;
  font-size: clamp(76px, 12.5vw, 176px);
  line-height: .72; letter-spacing: -.055em; font-weight: 900;
}
.logo span:first-child { color: #fff9ec; text-shadow: 0 6px 40px rgba(255,180,92,.18); }
.logo span:last-child {
  color: transparent;
  -webkit-text-stroke: 2px rgba(255,255,255,.74);
  text-shadow: 0 0 50px rgba(88,230,210,.24);
  margin-left: .06em;
}
.tagline { font-size: clamp(16px, 1.55vw, 22px); color: rgba(247,243,233,.82); margin: 28px 0 0; font-weight: 450; max-width: 560px; }
.start-features { display: flex; flex-wrap: wrap; gap: 8px; margin: 28px 0 34px; }
.start-features span {
  font-size: 12px; font-weight: 650; letter-spacing: .01em;
  padding: 9px 13px; border-radius: 999px;
  background: rgba(8,13,20,.55); border: 1px solid rgba(255,255,255,.12);
  backdrop-filter: blur(10px); color: #e6e2d8;
}
.start-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.primary-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 16px;
  padding: 16px 24px; border-radius: 14px;
  background: linear-gradient(135deg, #ffe0a7, #ffb45c 55%, #ff8f54);
  color: #17130e; font-weight: 850; font-size: 15px; letter-spacing: .02em;
  box-shadow: 0 14px 40px rgba(255,150,80,.28), inset 0 1px 0 rgba(255,255,255,.55);
  transition: transform .18s, box-shadow .18s;
}
.primary-btn:hover { transform: translateY(-2px); box-shadow: 0 18px 48px rgba(255,150,80,.38); }
.primary-btn b { font-size: 20px; }
.ghost-btn {
  padding: 15px 20px; border-radius: 14px; font-weight: 700; font-size: 14px;
  border: 1px solid rgba(255,255,255,.18); background: rgba(8,13,20,.45);
  backdrop-filter: blur(10px); transition: .2s;
}
.ghost-btn:hover { border-color: rgba(88,230,210,.55); color: var(--cyan); }
.start-note { color: var(--dim); font-size: 12px; margin: 14px 0 0; }
.start-controls { display: flex; gap: 22px; margin-top: 36px; color: var(--muted); font-size: 11px; flex-wrap: wrap; }
.start-controls div { display: flex; align-items: center; gap: 8px; }
kbd {
  font-family: inherit; font-size: 10px; font-weight: 800; color: #dbe4eb;
  padding: 5px 8px; border-radius: 6px;
  border: 1px solid rgba(255,255,255,.18); border-bottom-color: rgba(255,255,255,.28);
  background: rgba(255,255,255,.07);
}
.start-footer { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: flex-end; gap: 20px; }
.city-stats { display: flex; gap: 30px; }
.city-stats div { display: flex; flex-direction: column; gap: 2px; }
.city-stats strong { font-size: 20px; font-weight: 800; color: #fff6e7; }
.city-stats span { font-size: 10px; text-transform: uppercase; letter-spacing: .14em; color: var(--dim); }
.start-credit { font-size: 10px; letter-spacing: .16em; color: rgba(255,255,255,.3); text-transform: uppercase; }
.loading-bar { position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: rgba(255,255,255,.06); z-index: 4; }
.loading-bar i { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, var(--cyan), var(--orange)); transition: width .35s ease; box-shadow: 0 0 18px var(--cyan); }

/* ---------------------------------------------------------------- HUD */

.hud { position: fixed; inset: 0; z-index: 5; pointer-events: none; }
.hud > * { pointer-events: none; }
.hud button, .hud .interact-prompt, .hud .dialogue { pointer-events: auto; }
.hud-top {
  position: absolute; top: calc(18px + var(--safe-top)); left: calc(18px + var(--safe-left)); right: calc(18px + var(--safe-right));
  display: flex; justify-content: space-between; align-items: flex-start; gap: 18px;
}
.player-card { display: flex; align-items: center; gap: 12px; padding: 10px 12px; border-radius: 16px; min-width: 330px; }
.avatar {
  width: 42px; height: 42px; border-radius: 13px; position: relative;
  background: linear-gradient(145deg, #e87b55, #a94438);
  display: grid; place-items: center; font-size: 12px; font-weight: 900; letter-spacing: .05em;
  border: 1px solid rgba(255,255,255,.25); box-shadow: inset 0 1px 0 rgba(255,255,255,.25);
}
.online-dot { position: absolute; right: -2px; bottom: -2px; width: 10px; height: 10px; border-radius: 50%; background: var(--green); border: 2px solid #121821; }
.player-meta { display: flex; flex-direction: column; gap: 4px; }
.player-name { font-size: 13px; font-weight: 750; display: flex; align-items: center; gap: 7px; }
.tag { font-size: 8px; letter-spacing: .12em; padding: 3px 5px; border-radius: 4px; color: var(--cyan); background: rgba(88,230,210,.12); border: 1px solid rgba(88,230,210,.22); }
.player-time { display: flex; align-items: center; gap: 7px; font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }
.player-time i { width: 3px; height: 3px; border-radius: 50%; background: var(--dim); }
.money-chip { margin-left: 8px; padding: 8px 11px; border-radius: 10px; background: rgba(255,180,92,.1); border: 1px solid rgba(255,180,92,.22); display: flex; flex-direction: column; gap: 1px; }
.money-chip small { font-size: 8px; letter-spacing: .14em; color: rgba(255,209,147,.7); }
.money-chip strong { font-size: 16px; color: #ffdca8; font-weight: 800; }

.minimap-card { width: 196px; padding: 8px; border-radius: 17px; }
.map-head { display: flex; justify-content: space-between; align-items: center; padding: 2px 3px 7px; }
.map-loc { font-size: 10px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; color: #e8e1d3; }
.map-compass { font-size: 9px; color: var(--cyan); font-weight: 800; }
.minimap-card canvas { width: 100%; aspect-ratio: 1; display: block; border-radius: 11px; background: #1a2029; }
.map-foot { display: flex; justify-content: space-between; padding: 7px 3px 1px; font-size: 8px; letter-spacing: .12em; color: var(--dim); }
#interiorTag { color: var(--cyan); }

.objective {
  position: absolute; top: calc(20px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 12px;
  min-width: 320px; max-width: min(480px, 42vw);
  padding: 10px 13px; border-radius: 15px;
  border-color: rgba(255,180,92,.26);
  background: linear-gradient(135deg, rgba(38,28,18,.92), rgba(12,17,25,.88));
}
.objective-icon { width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center; font-size: 19px; background: rgba(255,180,92,.14); border: 1px solid rgba(255,180,92,.22); }
.objective-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.objective-copy small { font-size: 8px; letter-spacing: .16em; color: rgba(255,180,92,.8); font-weight: 800; }
.objective-copy strong { font-size: 12px; font-weight: 750; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.objective-copy span { font-size: 10px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.objective-timer { font-size: 15px; font-weight: 850; color: #ffd7a2; font-variant-numeric: tabular-nums; padding-left: 4px; }

.hud-bottom-left { position: absolute; left: calc(18px + var(--safe-left)); bottom: calc(18px + var(--safe-bottom)); display: flex; flex-direction: column; gap: 10px; }
.status-card { width: 236px; padding: 11px 12px; border-radius: 15px; display: flex; flex-direction: column; gap: 7px; }
.status-row { display: flex; align-items: center; gap: 7px; font-size: 10px; }
.stat-ico { width: 14px; text-align: center; font-size: 10px; opacity: .9; }
.stat-track { flex: 1; height: 5px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; }
.stat-track i { display: block; height: 100%; width: 100%; border-radius: 99px; transition: width .35s ease; }
.stat-track i.health { background: linear-gradient(90deg, #ff6b78, #ff9c7b); }
.stat-track i.energy { background: linear-gradient(90deg, #ffd34d, #ffb45c); }
.stat-track i.hunger { background: linear-gradient(90deg, #8fd46a, #5fc39c); }
.stat-track i.mood { background: linear-gradient(90deg, #b78bff, #58b6e6); }
.status-row b { width: 23px; text-align: right; font-size: 9px; color: var(--muted); font-variant-numeric: tabular-nums; }
.hint-line { display: flex; align-items: center; gap: 8px; font-size: 10px; color: var(--muted); padding-left: 3px; }
.hint-line kbd { font-size: 9px; padding: 3px 5px; }
.pulse-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); animation: livePulse 2.2s infinite; }

.hud-bottom-right { position: absolute; right: calc(18px + var(--safe-right)); bottom: calc(18px + var(--safe-bottom)); display: flex; flex-direction: column; align-items: flex-end; gap: 9px; }
.interact-prompt { display: flex; align-items: center; gap: 10px; padding: 9px 13px 9px 9px; border-radius: 14px; border-color: rgba(88,230,210,.3); background: rgba(8,18,22,.86); }
.interact-prompt .key { width: 34px; height: 34px; border-radius: 9px; display: grid; place-items: center; font-size: 13px; font-weight: 900; color: #10201d; background: var(--cyan); box-shadow: 0 0 18px rgba(88,230,210,.35); }
.interact-prompt div { display: flex; flex-direction: column; gap: 2px; }
.interact-prompt strong { font-size: 11px; font-weight: 750; }
.interact-prompt small { font-size: 9px; color: var(--muted); }
.right-actions { display: flex; align-items: center; gap: 8px; }
.round-btn {
  width: 52px; height: 52px; border-radius: 50%;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  border: 1px solid rgba(255,255,255,.16); background: rgba(8,13,20,.72);
  backdrop-filter: blur(12px); transition: .2s;
}
.round-btn span { font-size: 18px; line-height: 1; }
.round-btn small { font-size: 7px; letter-spacing: .08em; color: var(--muted); }
.round-btn.small { width: 38px; height: 38px; font-size: 13px; color: var(--muted); }
.round-btn:hover { border-color: rgba(88,230,210,.45); color: var(--cyan); transform: translateY(-1px); }
.desktop-hint { font-size: 9px; color: rgba(255,255,255,.32); letter-spacing: .04em; }

.toast-stack { position: absolute; left: 50%; bottom: calc(90px + var(--safe-bottom)); transform: translateX(-50%); display: flex; flex-direction: column-reverse; align-items: center; gap: 8px; width: min(460px, 88vw); }
.toast {
  display: flex; align-items: center; gap: 9px; padding: 9px 14px; border-radius: 12px;
  background: rgba(8,13,20,.9); border: 1px solid rgba(255,255,255,.14);
  backdrop-filter: blur(14px); font-size: 11px; color: #e9e4d8;
  box-shadow: 0 12px 30px rgba(0,0,0,.28); animation: toastIn .28s ease both;
}
.toast.good { border-color: rgba(143,212,106,.4); }
.toast.money { border-color: rgba(255,180,92,.45); }
.toast.bad { border-color: rgba(255,124,107,.45); }
.toast span { font-size: 15px; }
.toast.out { animation: toastOut .3s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(8px) scale(.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px) scale(.98); } }

.dialogue {
  position: absolute; left: 50%; bottom: calc(88px + var(--safe-bottom)); transform: translateX(-50%);
  width: min(620px, 92vw); padding: 14px 16px; border-radius: 18px;
  display: flex; align-items: center; gap: 13px;
  border-color: rgba(88,230,210,.22);
}
.dialogue-avatar { width: 42px; height: 42px; border-radius: 12px; display: grid; place-items: center; font-size: 20px; background: rgba(88,230,210,.1); border: 1px solid rgba(88,230,210,.18); }
.dialogue-copy { flex: 1; min-width: 0; }
.dialogue-copy strong { font-size: 11px; color: var(--cyan); letter-spacing: .06em; text-transform: uppercase; }
.dialogue-copy p { margin: 4px 0 0; font-size: 12px; line-height: 1.45; color: #eae5d9; }
.mini-btn { padding: 8px 12px; border-radius: 9px; background: rgba(255,255,255,.08); border: 1px solid var(--line); font-size: 10px; font-weight: 700; }
.mini-btn:hover { background: rgba(88,230,210,.15); border-color: rgba(88,230,210,.35); }

/* ---------------------------------------------------------------- mobile controls */

.mobile-controls { position: absolute; inset: 0; pointer-events: none; display: none; }
.joystick {
  position: absolute; left: calc(22px + var(--safe-left)); bottom: calc(28px + var(--safe-bottom));
  width: 126px; height: 126px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.18); background: radial-gradient(circle, rgba(255,255,255,.08), rgba(5,10,16,.28));
  backdrop-filter: blur(6px); pointer-events: auto; touch-action: none;
}
.joystick::after { content: ""; position: absolute; inset: 26px; border-radius: 50%; border: 1px dashed rgba(255,255,255,.14); }
.joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 50px; height: 50px; margin: -25px;
  border-radius: 50%; background: rgba(245,240,228,.82); border: 1px solid rgba(255,255,255,.65);
  box-shadow: 0 4px 18px rgba(0,0,0,.35); transition: transform .06s linear;
}
.mobile-actions { position: absolute; right: calc(20px + var(--safe-right)); bottom: calc(32px + var(--safe-bottom)); display: flex; align-items: flex-end; gap: 12px; pointer-events: auto; }
.mobile-action, .mobile-sprint {
  width: 74px; height: 74px; border-radius: 50%;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  font-size: 21px; font-weight: 900;
  background: rgba(88,230,210,.9); color: #0d201c;
  border: 1px solid rgba(255,255,255,.4); box-shadow: 0 8px 28px rgba(0,0,0,.35);
  pointer-events: auto; touch-action: none;
}
.mobile-action small, .mobile-sprint small { font-size: 7px; letter-spacing: .08em; font-weight: 800; }
.mobile-sprint { width: 56px; height: 56px; font-size: 16px; background: rgba(10,16,24,.75); color: var(--orange); border-color: rgba(255,180,92,.35); }
.mobile-action:active, .mobile-sprint:active { transform: scale(.94); }

/* ---------------------------------------------------------------- phone */

.phone-panel {
  position: fixed; inset: 0; z-index: 14;
  display: flex; justify-content: flex-end; align-items: stretch;
  padding: calc(18px + var(--safe-top)) calc(18px + var(--safe-right)) calc(18px + var(--safe-bottom)) 18px;
  background: rgba(2,5,9,.35); backdrop-filter: blur(5px);
}
.phone-shell {
  width: min(420px, 100%); max-height: 100%;
  display: flex; flex-direction: column;
  border-radius: 34px; background: linear-gradient(180deg, #101721, #090e15);
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: -20px 0 80px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.08);
  padding: 12px 12px 10px; position: relative;
  animation: phoneIn .38s cubic-bezier(.2,.9,.2,1) both;
}
@keyframes phoneIn { from { opacity: 0; transform: translateX(30px) scale(.98); } to { opacity: 1; transform: none; } }
.phone-notch { width: 88px; height: 20px; border-radius: 0 0 13px 13px; background: #05080d; margin: -12px auto 9px; }
.phone-head { display: flex; align-items: center; gap: 10px; padding: 3px 6px 10px; }
.phone-head > div:first-child { display: flex; flex-direction: column; gap: 1px; flex: 1; }
.phone-head small { font-size: 8px; letter-spacing: .14em; color: var(--cyan); text-transform: uppercase; }
.phone-head strong { font-size: 16px; font-weight: 800; }
.phone-cash { font-size: 14px; font-weight: 850; color: #ffdca8; }
.phone-head .icon-btn { width: 31px; height: 31px; font-size: 13px; }
.phone-tabs { display: flex; gap: 4px; overflow-x: auto; padding: 2px 2px 9px; scrollbar-width: none; }
.phone-tabs::-webkit-scrollbar { display: none; }
.phone-tab { flex: 0 0 auto; padding: 7px 10px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--dim); border: 1px solid transparent; }
.phone-tab.active { color: var(--ink); background: rgba(255,255,255,.09); border-color: rgba(255,255,255,.12); }
.phone-body { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; border-radius: 20px; background: #0b1119; border: 1px solid rgba(255,255,255,.07); padding: 14px; scrollbar-width: thin; scrollbar-color: #33404d transparent; }
.phone-tab-page { display: none; animation: pageIn .22s ease both; }
.phone-tab-page.active { display: block; }
@keyframes pageIn { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }
.page-title { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; margin-bottom: 12px; }
.page-title span { font-size: 18px; font-weight: 800; }
.page-title small { font-size: 9px; color: var(--dim); }
#bigMap { width: 100%; aspect-ratio: 1; border-radius: 16px; background: #161d26; display: block; border: 1px solid rgba(255,255,255,.08); }
.map-legend { display: flex; gap: 14px; margin-top: 10px; font-size: 9px; color: var(--muted); }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.map-legend i { width: 7px; height: 7px; border-radius: 2px; }
.map-tip { margin-top: 9px; font-size: 9px; color: var(--dim); line-height: 1.5; }
.inventory-list, .wardrobe-list, .job-list, .settings-list { display: flex; flex-direction: column; gap: 8px; }
.inv-item { display: flex; align-items: center; gap: 10px; padding: 10px; border-radius: 12px; background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.07); }
.inv-icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; font-size: 18px; background: rgba(255,255,255,.06); }
.inv-copy { flex: 1; display: flex; flex-direction: column; gap: 2px; }
.inv-copy strong { font-size: 11px; }
.inv-copy span { font-size: 9px; color: var(--dim); }
.inv-qty { font-size: 10px; color: var(--orange); font-weight: 800; }
.empty-state { padding: 30px 20px; text-align: center; color: var(--dim); font-size: 11px; line-height: 1.6; border: 1px dashed rgba(255,255,255,.1); border-radius: 14px; }
.empty-state b { display: block; font-size: 22px; margin-bottom: 8px; }
.outfit-preview { display: flex; align-items: center; gap: 14px; padding: 14px; border-radius: 14px; background: linear-gradient(135deg, rgba(255,180,92,.1), rgba(88,230,210,.06)); border: 1px solid rgba(255,255,255,.1); margin-bottom: 13px; }
.outfit-person { width: 54px; height: 76px; position: relative; }
.outfit-person i { position: absolute; left: 16px; top: 0; width: 22px; height: 22px; border-radius: 50%; background: #d6a77d; border: 2px solid rgba(255,255,255,.2); }
.outfit-person b { position: absolute; left: 8px; top: 22px; width: 38px; height: 34px; border-radius: 10px 10px 5px 5px; background: #e86b4f; }
.outfit-person em { position: absolute; left: 13px; top: 55px; width: 28px; height: 21px; border-radius: 4px; background: #293241; }
.outfit-preview > div:last-child { display: flex; flex-direction: column; gap: 3px; }
.outfit-preview strong { font-size: 13px; }
.outfit-preview span { font-size: 9px; color: var(--green); }
.wear-item { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 11px; background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.07); text-align: left; width: 100%; }
.wear-item:hover { border-color: rgba(88,230,210,.3); }
.wear-item.active { border-color: rgba(88,230,210,.55); background: rgba(88,230,210,.08); }
.wear-item .inv-icon { width: 30px; height: 30px; font-size: 15px; }
.wear-item strong { font-size: 10px; flex: 1; }
.wear-item span { font-size: 9px; color: var(--dim); }
.home-status { padding: 18px; border-radius: 16px; background: linear-gradient(135deg, rgba(143,212,106,.12), rgba(88,230,210,.04)); border: 1px solid rgba(143,212,106,.22); margin-bottom: 13px; }
.home-status h3 { margin: 0 0 5px; font-size: 17px; }
.home-status p { margin: 0; font-size: 10px; line-height: 1.5; color: var(--muted); }
.home-status.locked { background: rgba(255,255,255,.04); border-color: rgba(255,255,255,.08); }
.home-actions { display: flex; flex-direction: column; gap: 8px; }
.wide-btn { width: 100%; padding: 13px; border-radius: 11px; background: linear-gradient(135deg, #ffe0a7, #ffb45c); color: #18130d; font-weight: 800; font-size: 12px; }
.wide-btn.secondary { background: rgba(255,255,255,.06); color: var(--ink); border: 1px solid var(--line); }
.wide-btn:disabled { opacity: .35; cursor: not-allowed; }
.home-tip { margin-top: 12px; font-size: 9px; line-height: 1.6; color: var(--dim); }
.job-card { padding: 12px; border-radius: 14px; background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.08); display: flex; flex-direction: column; gap: 8px; }
.job-card-top { display: flex; align-items: center; gap: 10px; }
.job-icon { width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; font-size: 20px; background: rgba(255,255,255,.07); }
.job-card h3 { margin: 0; font-size: 13px; }
.job-card p { margin: 0; font-size: 9px; line-height: 1.5; color: var(--muted); }
.job-meta { display: flex; gap: 12px; font-size: 9px; color: var(--dim); }
.job-meta b { color: var(--orange); }
.job-btn { padding: 9px 12px; border-radius: 8px; background: rgba(88,230,210,.14); border: 1px solid rgba(88,230,210,.28); color: var(--cyan); font-weight: 800; font-size: 10px; }
.job-btn:hover { background: rgba(88,230,210,.22); }
.setting-row { width: 100%; display: flex; justify-content: space-between; align-items: center; padding: 13px; border-radius: 11px; background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.07); font-size: 11px; text-align: left; }
.setting-row b { font-size: 9px; color: var(--cyan); letter-spacing: .08em; }
.setting-row.danger b { color: var(--coral); }
.settings-note { margin-top: 14px; font-size: 9px; line-height: 1.6; color: var(--dim); }
.phone-homebar { width: 120px; height: 4px; border-radius: 99px; background: rgba(255,255,255,.2); margin: 10px auto 2px; flex: 0 0 auto; }

/* ---------------------------------------------------------------- modals */

.modal-layer {
  position: fixed; inset: 0; z-index: 18;
  display: flex; align-items: center; justify-content: center;
  padding: calc(18px + var(--safe-top)) calc(18px + var(--safe-right)) calc(18px + var(--safe-bottom)) calc(18px + var(--safe-left));
  background: rgba(2,5,9,.6); backdrop-filter: blur(7px);
}
.modal-card {
  width: min(920px, 100%); max-height: 100%;
  display: flex; flex-direction: column;
  border-radius: 24px; background: linear-gradient(180deg, #111923, #0a0f17);
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,.07);
  animation: modalIn .32s cubic-bezier(.2,.9,.2,1) both;
  overflow: hidden;
}
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
.modal-head { display: flex; align-items: center; gap: 14px; padding: 18px 20px; border-bottom: 1px solid rgba(255,255,255,.08); flex: 0 0 auto; }
.shop-badge { width: 54px; height: 54px; border-radius: 15px; display: grid; place-items: center; font-size: 26px; background: rgba(255,180,92,.1); border: 1px solid rgba(255,180,92,.22); }
.modal-head > div:nth-child(2) { flex: 1; min-width: 0; }
.modal-head small { font-size: 8px; letter-spacing: .17em; color: var(--orange); font-weight: 800; }
.modal-head h2 { margin: 2px 0; font-size: 22px; letter-spacing: -.02em; }
.modal-head p { margin: 0; font-size: 10px; color: var(--muted); }
.shop-balance { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; padding-right: 4px; }
.shop-balance small { font-size: 8px; color: var(--dim); }
.shop-balance strong { font-size: 18px; color: #ffdca8; }
.modal-close { margin-left: 2px; }
.shop-grid { padding: 18px 20px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; overflow-y: auto; }
.shop-item {
  display: flex; flex-direction: column; gap: 8px; padding: 13px; border-radius: 15px;
  background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.08);
  transition: .2s; min-height: 150px;
}
.shop-item:hover { border-color: rgba(255,180,92,.3); background: rgba(255,255,255,.06); transform: translateY(-1px); }
.shop-item-top { display: flex; align-items: flex-start; gap: 10px; }
.shop-item .item-icon { width: 42px; height: 42px; border-radius: 11px; display: grid; place-items: center; font-size: 22px; background: rgba(255,255,255,.06); flex: 0 0 auto; }
.shop-item h3 { margin: 0 0 2px; font-size: 12px; }
.shop-item p { margin: 0; font-size: 9px; line-height: 1.45; color: var(--dim); }
.shop-item .item-price { font-size: 11px; font-weight: 800; color: #ffdca8; }
