  const b = document.getElementById('startBtn');
  const r = b.getBoundingClientRect();
  const el = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
  return {
    rect: [r.x, r.y, r.width, r.height],
    top: el && (el.tagName + '#' + el.id + '.' + el.className),
    anim: getComputedStyle(document.querySelector('.start-content')).animationName,
    animState: getComputedStyle(document.querySelector('.start-content')).animationPlayState,
    pointer: getComputedStyle(b).pointerEvents,
    disabled: b.disabled,
  };
});
console.log('info', info);
await page.evaluate(() => document.getElementById('startBtn').click());
await page.waitForTimeout(3000);
await page.screenshot({ path: '/tmp/opencode/shots/game-desktop.png' });
