:root {
  --ink: #f6f2e8;
  --muted: #a9b4c2;
  --dim: #778392;
  --panel: rgba(10, 16, 24, 0.78);
  --panel-strong: rgba(8, 12, 18, 0.94);
  --line: rgba(255, 255, 255, 0.12);
  --cyan: #58e6d2;
  --orange: #ffb45c;
  --coral: #ff7c6b;
  --violet: #b78bff;
  --green: #8fd46a;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
  --radius: 18px;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0b1018;
  color: var(--ink);
  font-family: "Inter", "SF Pro Display", "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  touch-action: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }

#game, #game canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.hidden { display: none !important; }

  .status-row b { font-size: 8px; }
  .hud-bottom-right { right: calc(12px + var(--safe-right)); bottom: calc(176px + var(--safe-bottom)); }
  .round-btn { width: 44px; height: 44px; }
  .round-btn.small { display: none; }
  .round-btn span { font-size: 15px; }
  .round-btn small { font-size: 6px; }
  .interact-prompt { max-width: 210px; padding: 7px 10px 7px 7px; }
  .interact-prompt .key { width: 28px; height: 28px; font-size: 11px; }
  .interact-prompt strong { font-size: 9px; }
  .interact-prompt small { display: none; }
  .objective { bottom: calc(150px + var(--safe-bottom)); padding: 8px 10px; }
  .objective-icon { width: 30px; height: 30px; font-size: 15px; }
  .objective-copy strong { font-size: 10px; }
  .objective-copy span { font-size: 8px; }
  .objective-timer { font-size: 12px; }
  .toast-stack { bottom: calc(240px + var(--safe-bottom)); }
  .dialogue { bottom: calc(150px + var(--safe-bottom)); width: calc(100% - 24px); }
  .phone-panel { padding: 0; }
  .phone-shell { width: 100%; max-height: 100%; border-radius: 0; border: 0; padding: calc(8px + var(--safe-top)) 10px calc(6px + var(--safe-bottom)); }
  .phone-notch { display: none; }
  .phone-homebar { margin-bottom: 2px; }
  .shop-grid { grid-template-columns: 1fr; padding: 12px; gap: 8px; }
  .modal-layer { padding: calc(8px + var(--safe-top)) calc(8px + var(--safe-right)) calc(8px + var(--safe-bottom)) calc(8px + var(--safe-left)); }
  .modal-card { border-radius: 18px; }
  .modal-head { padding: 13px; gap: 10px; }
  .shop-badge { width: 42px; height: 42px; font-size: 20px; border-radius: 11px; }
  .modal-head h2 { font-size: 18px; }
  .modal-head p { font-size: 9px; }
  .shop-balance { display: none; }
  .modal-foot { padding: 10px 13px; font-size: 8px; }
  .barista-options { grid-template-columns: 1fr; padding: 0 14px; }
  .customer-card { margin: 12px 14px; }
  .barista-top { padding: 16px 14px 10px; }
  .barista-timer { margin: 0 14px; }
  .barista-foot { padding: 12px 14px 16px; flex-direction: column; }
  .how-grid { grid-template-columns: 1fr; padding: 12px; }
  .start-screen { padding: calc(18px + var(--safe-top)) calc(20px + var(--safe-right)) calc(16px + var(--safe-bottom)) calc(20px + var(--safe-left)); }
  .start-content { margin-top: auto; margin-bottom: auto; padding-bottom: 3vh; }
  .logo { font-size: clamp(62px, 21vw, 108px); }
  .tagline { font-size: 15px; margin-top: 20px; }
  .start-features { margin: 20px 0 26px; }
  .start-features span { font-size: 10px; padding: 7px 10px; }
  .primary-btn { padding: 14px 20px; font-size: 14px; }
  .start-note { font-size: 10px; }
  .start-footer { flex-direction: column; align-items: flex-start; gap: 8px; }
  .city-stats { gap: 20px; }
  .city-stats strong { font-size: 16px; }
  .start-credit { display: none; }
  .start-top-actions #saveHint { display: none; }
}

@media (max-height: 560px) and (orientation: landscape) {
  .start-content { padding: 0; }
  .logo { font-size: 64px; }
  .tagline { margin-top: 12px; font-size: 13px; }
  .start-features { margin: 12px 0 16px; }
  .start-controls, .start-footer { display: none; }
  .hud-bottom-left { bottom: calc(12px + var(--safe-bottom)); }
  .hud-bottom-right { bottom: calc(12px + var(--safe-bottom)); }
  .status-card { width: 150px; }
  .objective { bottom: calc(120px + var(--safe-bottom)); }
  .joystick { width: 100px; height: 100px; }
  .mobile-action { width: 62px; height: 62px; }
}

