import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 30000 });
await page.waitForTimeout(1000);
console.log('metrics', await page.evaluate(() => ({
  inner: [innerWidth, innerHeight],
  body: [document.body.clientWidth, document.body.clientHeight],
  game: (() => { const g = document.getElementById('game'); const r = g.getBoundingClientRect(); return [r.width, r.height, r.top]; })(),
  canvas: (() => { const c = document.querySelector('#game canvas'); const r = c.getBoundingClientRect(); return [c.width, c.height, r.width, r.height, r.top]; })(),
  hud: (() => { const h = document.getElementById('hud'); const r = h.getBoundingClientRect(); return [r.width, r.height, r.top]; })(),
  scroll: [document.documentElement.scrollHeight, document.body.scrollHeight],
  dpr: devicePixelRatio,
})));
await page.evaluate(() => document.getElementById('startBtn').click());
await page.waitForTimeout(1800);
await page.screenshot({ path: '/tmp/opencode/shots/game-mobile.png' });
console.log('after', await page.evaluate(() => ({ yaw: window.harborGame.cameraYaw, rot: window.harborGame.player.rotation.y, pos: window.harborGame.player.position.toArray() })));
await browser.close();

