import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  page.on('pageerror', e => console.log(name, '[pageerror]', e.message));
  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
  await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 30000 });
  await page.evaluate(() => document.getElementById('startBtn').click());
  await page.waitForTimeout(2200);
  const boxes = await page.evaluate(() => {
    const pick = (sel) => { const el = document.querySelector(sel); if (!el) return null; const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return { rect: [r.x, r.y, r.width, r.height], display: s.display, visibility: s.visibility }; };
    return {
      canvas: pick('#game canvas'),
      status: pick('.status-card'),
      hudLeft: pick('.hud-bottom-left'),
      hudRight: pick('.hud-bottom-right'),
      phoneBtn: pick('#phoneBtn'),
      joystick: pick('#joystick'),
      mobileAction: pick('#mobileAction'),
      hud: pick('#hud'),
      toast: pick('.toast-stack'),
      inner: [innerWidth, innerHeight],
      dpr: devicePixelRatio,
    };
  });
  console.log(name, JSON.stringify(boxes));
  await page.screenshot({ path: `/tmp/opencode/shots/start-${name}.png` });
  await page.close();
}
await browser.close();

