import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('[console error]', m.text()); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 30000 });
await page.evaluate(() => document.getElementById('startBtn').click());
await page.waitForTimeout(1500);

const state = () => page.evaluate(() => ({
  pos: window.harborGame.player.position.toArray().map(n => +n.toFixed(2)),
  cash: window.harborGame.state.cash,
  inside: window.harborGame.insideId,
  driving: Boolean(window.harborGame.driving),
  prompt: document.getElementById('interactPrompt').classList.contains('hidden') ? null : document.getElementById('promptLabel').textContent,
  inventory: window.harborGame.state.inventory,
  blocking: window.harborGame.blocking,
}));

console.log('initial', await state());
// Walk west using W (camera looks west).
await page.keyboard.down('KeyW');
await page.waitForTimeout(1200);
await page.keyboard.up('KeyW');
console.log('after walk', await state());

// Teleport to mall door and interact.
await page.evaluate(() => { window.harborGame.player.position.set(0, 0.2, 17.3); });
await page.waitForTimeout(400);
console.log('at door', await state());
await page.keyboard.press('KeyE');
await page.waitForTimeout(900);
console.log('after enter', await state());
await page.screenshot({ path: '/tmp/opencode/shots/mall-interior.png' });

// Teleport to mall counter and interact.
await page.evaluate(() => { window.harborGame.player.position.set(0, -899.9, -5.05); });
await page.waitForTimeout(400);
console.log('at counter', await state());
await page.keyboard.press('KeyE');
await page.waitForTimeout(700);
console.log('shop open', await page.evaluate(() => !document.getElementById('shopModal').classList.contains('hidden')), await page.locator('#shopName').textContent());
await page.screenshot({ path: '/tmp/opencode/shots/mall-shop.png' });
const buy = page.locator('#shopItems [data-buy]').first();
console.log('first buy text', await buy.textContent());
await buy.click();
await page.waitForTimeout(500);
console.log('after buy', await state());
await page.screenshot({ path: '/tmp/opencode/shots/mall-shop-bought.png' });
await page.locator('[data-close="shop"]').first().click();
await page.waitForTimeout(300);

// Exit interior via exit.
await page.evaluate(() => { window.harborGame.player.position.set(0, -899.9, 9.0); });
await page.waitForTimeout(400);
console.log('at exit', await state());
await page.keyboard.press('KeyE');
await page.waitForTimeout(700);
console.log('after exit', await state());

// Teleport to car and enter.
await page.evaluate(() => { window.harborGame.player.position.set(13, 0.2, 21); });
await page.waitForTimeout(400);
console.log('at car', await state());
await page.keyboard.press('KeyE');
await page.waitForTimeout(700);
console.log('after car', await state());
await page.keyboard.down('KeyW');
await page.waitForTimeout(1500);
await page.keyboard.up('KeyW');
console.log('after drive', await state());
await page.screenshot({ path: '/tmp/opencode/shots/driving.png' });

// Phone.
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
await page.keyboard.press('Tab');
await page.waitForTimeout(500);
console.log('phone open', await page.evaluate(() => !document.getElementById('phonePanel').classList.contains('hidden')));
await page.screenshot({ path: '/tmp/opencode/shots/phone.png' });
for (const tab of ['inventory', 'wardrobe', 'home', 'jobs', 'settings']) {
  await page.locator(`.phone-tab[data-tab="${tab}"]`).click();
  await page.waitForTimeout(200);
}
await page.screenshot({ path: '/tmp/opencode/shots/phone-jobs.png' });
await page.keyboard.press('Tab');
await page.waitForTimeout(300);

await browser.close();

