import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 960, height: 640 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('[pageerror]', e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('[console error]', m.text()); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 30000 });
await page.evaluate(() => document.getElementById('startBtn').click());
await page.waitForTimeout(800);
// speed up software rendering for functional tests
await page.evaluate(() => {
  const g = window.harborGame;
  g.renderer.shadowMap.enabled = false;
  g.renderer.setPixelRatio(0.5);
});

const info = () => page.evaluate(() => {
  const g = window.harborGame;
  return {
    cash: g.state.cash, minutes: Math.round(g.state.minutes), day: g.state.day,
    inside: g.insideId, driving: !!g.driving, job: g.state.job,
    stats: { ...g.state.stats }, inv: Object.keys(g.state.inventory),
    wardrobe: g.state.wardrobe.map(w => w.name), house: g.state.house, pet: g.state.pet?.name || null,
    cars: g.state.ownedCars.map(c => c.name), blocking: g.blocking,
    prompt: document.getElementById('interactPrompt').classList.contains('hidden') ? null : document.getElementById('promptLabel').textContent,
    shopOpen: !document.getElementById('shopModal').classList.contains('hidden'),
    jobOpen: !document.getElementById('jobModal').classList.contains('hidden'),
    phoneOpen: !document.getElementById('phonePanel').classList.contains('hidden'),
    objective: document.getElementById('objectivePanel').classList.contains('hidden') ? null : document.getElementById('objText').textContent,
  };
});
const teleport = async (x, z) => { await page.evaluate(([x,z]) => { window.harborGame.player.position.set(x, window.harborGame.insideId ? -899.9 : 0.2, z); }, [x,z]); await page.waitForTimeout(350); };
const pressE = async () => { await page.keyboard.press('KeyE'); await page.waitForTimeout(450); };

console.log('start', await info());

// Phone
await page.keyboard.press('Tab');
await page.waitForTimeout(500);
console.log('phone', await info());
await page.screenshot({ path: '/tmp/opencode/shots/test-phone-map.png' });
await page.locator('.phone-tab[data-tab="jobs"]').click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/shots/test-phone-jobs.png' });
await page.keyboard.press('Tab');
await page.waitForTimeout(300);

// Job center
await teleport(45.7, -60);
console.log('job door', await info());
await pressE();
console.log('job interior', await info());
const jc = await page.evaluate(() => { const g = window.harborGame; return g.currentInterior.interactables.map(i => ({ label: i.label, pos: [i.position.x, i.position.z] })); });
console.log('jc items', jc);
await teleport(45.6, -60);
await pressE();
console.log('job modal', await info());
await page.screenshot({ path: '/tmp/opencode/shots/test-job-modal.png' });
await page.locator('[data-pick-job="courier"]').click();
await page.waitForTimeout(500);
console.log('job started', await info());

// Courier pickup
await teleport(-118, 45);
