import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 960, height: 640 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('[pageerror]', e.message); });
page.on('console', m => { if (m.type() === 'error') console.log('[console error]', m.text()); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 30000 });
await page.evaluate(() => document.getElementById('startBtn').click());
await page.waitForTimeout(700);
await page.evaluate(() => {
  const g = window.harborGame;
  g.renderer.shadowMap.enabled = false;
  g.renderer.setPixelRatio(0.5);
});

const info = () => page.evaluate(() => {
  const g = window.harborGame;
  return {
    cash: Math.round(g.state.cash), minutes: Math.round(g.state.minutes), day: g.state.day,
    inside: g.insideId, driving: !!g.driving, job: g.state.job,
    hunger: Math.round(g.state.stats.hunger), energy: Math.round(g.state.stats.energy),
    inv: Object.keys(g.state.inventory), wardrobe: g.state.wardrobe.map(w => w.name),
    house: g.state.house, pet: g.state.pet?.name || null, cars: g.state.ownedCars.map(c => c.name),
    blocking: g.blocking,
    prompt: document.getElementById('interactPrompt').classList.contains('hidden') ? null : document.getElementById('promptLabel').textContent,
    shopOpen: !document.getElementById('shopModal').classList.contains('hidden'),
    jobOpen: !document.getElementById('jobModal').classList.contains('hidden'),
    phoneOpen: !document.getElementById('phonePanel').classList.contains('hidden'),
    objective: document.getElementById('objectivePanel').classList.contains('hidden') ? null : document.getElementById('objText').textContent,
  };
});
const wait = (ms = 300) => page.waitForTimeout(ms);
const enter = async (id) => { await page.evaluate(id => window.harborGame.enterBusiness(id), id); await wait(450); };
const exitInterior = async () => { await page.evaluate(() => window.harborGame.exitInterior()); await wait(350); };
const goInteract = async (x, z, useKey = false) => {
  await page.evaluate(([x,z]) => {
    const g = window.harborGame;
    g.player.position.set(x, g.insideId ? g.currentInterior.bounds.baseY + 0.1 : 0.2, z);
    g.updateInteractions();
  }, [x,z]);
  await wait(200);
  if (useKey) { await page.keyboard.press('KeyE'); await wait(450); }
  else { await page.evaluate(() => window.harborGame.interact()); await wait(450); }
};
const interiorItem = async (needle) => page.evaluate((needle) => {
  const g = window.harborGame;
  const item = g.currentInterior.interactables.find(i => i.label.toLowerCase().includes(needle.toLowerCase()) || i.id.includes(needle));
  return item ? { id: item.id, label: item.label, pos: [item.position.x, item.position.z] } : null;
}, needle);

console.log('start', await info());

// Phone tabs
await page.keyboard.press('Tab'); await wait(450);
console.log('phone open', (await info()).phoneOpen);
await page.locator('.phone-tab[data-tab="jobs"]').click(); await wait(250);
await page.screenshot({ path: '/tmp/opencode/shots/test-phone-jobs.png' });
await page.keyboard.press('Tab'); await wait(250);

// Job center via door and E
await page.evaluate(() => { window.harborGame.player.position.set(45.7, 0.2, -60); window.harborGame.updateInteractions(); });
await wait(250);
console.log('job door prompt', (await info()).prompt);
await page.keyboard.press('KeyE'); await wait(450);
console.log('job interior', await info());
const jcCounter = await interiorItem('jobs');
await goInteract(jcCounter.pos[0], jcCounter.pos[1], true);
console.log('job modal open', (await info()).jobOpen);
await page.screenshot({ path: '/tmp/opencode/shots/test-job-modal.png' });
await page.locator('[data-pick-job="courier"]').click(); await wait(500);
console.log('job started', await info());
// Pickup
await page.evaluate(() => { const g = window.harborGame; g.exitInterior(); g.player.position.set(-118, 0.2, 45); g.updateInteractions(); });
await wait(400);
console.log('pickup prompt', (await info()).prompt);
await page.keyboard.press('KeyE'); await wait(450);
console.log('after pickup', await info());
// Dropoff
await page.evaluate(() => { const g = window.harborGame; g.player.position.set(60, 0.2, 136); g.updateInteractions(); });
await wait(300);
console.log('dropoff prompt', (await info()).prompt);
await page.keyboard.press('KeyE'); await wait(450);
console.log('after dropoff', await info());

// Supermarket
await enter('supermarket');
const martCounter = await interiorItem('FreshMart');
console.log('mart counter', martCounter);
await goInteract(martCounter.pos[0], martCounter.pos[1], true);
console.log('mart shop open', (await info()).shopOpen);
await page.locator('[data-buy="burger"]').click(); await wait(450);
console.log('after burger', await info());
await page.screenshot({ path: '/tmp/opencode/shots/test-supermarket-shop.png' });
await page.locator('[data-close="shop"]').first().click(); await wait(250);

// Hotel
await exitInterior();
await enter('hotel');
const bed = await interiorItem('room');
console.log('hotel bed', bed);
await goInteract(bed.pos[0], bed.pos[1], true);
console.log('hotel shop open', (await info()).shopOpen);
await page.locator('[data-buy="room"]').click(); await wait(600);
console.log('after hotel room', await info());
console.log('shop after room', (await info()).shopOpen);

// House, pet, car direct
await page.evaluate(() => {
  const g = window.harborGame;
  g.exitInterior();
  g.state.cash = 30000;
  g.ui.openShop({ id: 'realestate', name: 'Key & Stone', type: 'realestate', category: 'Homes', tagline: '', accent: '#8fd46a' });
});
await wait(350);
await page.locator('[data-buy="house_maple"]').click(); await wait(450);
console.log('after house', await info());
await page.locator('[data-close="shop"]').first().click(); await wait(200);
await page.evaluate(() => {
  const g = window.harborGame;
  g.ui.openShop({ id: 'petstore', name: 'Paws & Co.', type: 'petstore', category: 'Pets', tagline: '', accent: '#ffad5c' });
});
await wait(300);
await page.locator('[data-buy="dog"]').click(); await wait(450);
console.log('after pet', await info());
await page.locator('[data-close="shop"]').first().click(); await wait(200);
await page.evaluate(() => {
  const g = window.harborGame;
  g.ui.openShop({ id: 'dealership', name: 'Volt Motors', type: 'dealership', category: 'Vehicles', tagline: '', accent: '#4fd8ff' });
});
await wait(300);
await page.locator('[data-buy="car_compact"]').click(); await wait(450);
console.log('after car', await info());
await page.locator('[data-close="shop"]').first().click(); await wait(200);

// Driving
await page.evaluate(() => { const g = window.harborGame; g.player.position.set(13, 0.2, 21); g.updateInteractions(); });
await wait(300);
console.log('car prompt', (await info()).prompt);
await page.keyboard.press('KeyE'); await wait(450);
console.log('driving', await info());
await page.evaluate(() => { const g = window.harborGame; if (g.driving) g.driving.speed = 10; });
await wait(1500);
console.log('drive pos', await page.evaluate(() => window.harborGame.driving?.group.position.toArray()));
await page.keyboard.press('KeyE'); await wait(400);
console.log('after exit car', await info());

// Wardrobe equip
await page.evaluate(() => { const g = window.harborGame; g.equipWardrobe('starter'); });
console.log('errors', errors);
await browser.close();

