await page.evaluate(() => { const g = window.harborGame; g.renderer.shadowMap.enabled = false; g.renderer.setPixelRatio(0.5); });
console.log('controls', await page.evaluate(() => {
  const el = document.getElementById('mobileControls');
  const r = el.getBoundingClientRect();
  return { display: getComputedStyle(el).display, rect: [r.x, r.y, r.width, r.height], joystick: document.getElementById('joystick').getBoundingClientRect().toJSON(), action: document.getElementById('mobileAction').getBoundingClientRect().toJSON() };
}));
const before = await page.evaluate(() => window.harborGame.player.position.toArray());
const joy = await page.locator('#joystick').boundingBox();
await page.mouse.move(joy.x + joy.width/2, joy.y + joy.height/2);
await page.mouse.down();
await page.mouse.move(joy.x + joy.width/2, joy.y + joy.height/2 - 45, { steps: 5 });
await page.waitForTimeout(1200);
await page.mouse.up();
await page.waitForTimeout(300);
const after = await page.evaluate(() => window.harborGame.player.position.toArray());
console.log('joystick moved', before, after, 'delta', Math.hypot(after[0]-before[0], after[2]-before[2]));
// Teleport to mall door and use mobile action
