import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('startBtn').disabled, null, { timeout: 30000 });
await page.locator('#startBtn').click({ force: true });
await page.waitForTimeout(1500);
for (const id of ['mall', 'gym', 'bar', 'hotel', 'dealership', 'house']) {
  await page.evaluate((id) => {
    const g = window.harborGame;
    if (g.insideId) g.exitInterior();
    g.enterBusiness(id);
  }, id);
  await page.waitForTimeout(1800);
  await page.screenshot({ path: `/tmp/opencode/shots/interior-${id}.png` });
  console.log('shot', id);
}
await browser.close();

